	punpcklqdq xmm10, xmm3
	movdqu xmm3, [rdi]
	movdqu xmm2, [rdi+16]
	pshufd xmm3, xmm3, 0xb1
	pshufd xmm2, xmm2, 0x1b
	movdqa xmm1, xmm3
	palignr xmm1, xmm2, 8
	pblendw xmm2, xmm3, 0xf0
