	movdqa xmm8, xmm1
	movdqa xmm9, xmm2
	movdqu xmm4, [rsi+0]
	pshufb xmm4, xmm10
	movdqu xmm0, [rcx+0]
	paddd xmm0, xmm4
	sha256rnds2 xmm2, xmm1
	pshufd xmm0, xmm0, 0xe
	sha256rnds2 xmm1, xmm2
	movdqu xmm5, [rsi+16]
	pshufb xmm5, xmm10
	movdqu xmm0, [rcx+16]
	paddd xmm0, xmm5
	sha256rnds2 xmm2, xmm1
	pshufd xmm0, xmm0, 0xe
	sha256rnds2 xmm1, xmm2
	sha256msg1 xmm4, xmm5
	movdqu xmm6, [rsi+32]
